scripts.postbuild:
node -e "
const fs = require('fs');
const dir = '.output/public/_nuxt';
const files = fs.readdirSync(dir);
const css = files.find(f => f.includes('entry') && f.endsWith('.css')) || files.find(f => f.endsWith('.css') && !f.includes('error') && !f.includes('404') && !f.includes('500'));
const js = files.find(f => f.includes('entry') && f.endsWith('.js')) || files.find(f => f.endsWith('.js') && !f.includes('error'));
const html = '<!DOCTYPE html><html lang=de><head><meta charset=UTF-8><meta name=viewport content=width=device-width,initial-scale=1><title>Plexora</title><link rel=stylesheet href=/_nuxt/' + css + '></head><body><div id=__nuxt></div><script type=module src=/_nuxt/' + js + '><\/script></body></html>';
fs.writeFileSync('.output/public/index.html', html);
fs.cpSync('.output/public', 'dist', { recursive: true });
console.log('index.html erstellt mit', css, js);
"
